define("enrol_coursecompleted/groupselector",["core/ajax"],function(Ajax){return{processResults:function(selector,results){return results;},transport:function(selector,query,success,failure){var input=document.querySelector('[name="customint1"]');var courseid=input?parseInt(input.value,10):0;if(!courseid){success([]);return;}Ajax.call([{methodname:"core_group_get_course_groups",args:{courseid:courseid}}])[0].then(function(groups){var q=(query||"").toLowerCase();var out=[];groups.forEach(function(g){if(q===""||g.name.toLowerCase().indexOf(q)!==-1){out.push({value:g.id,label:g.name});}});success(out);return out;}).catch(failure);}};});
